  uint32_t refr_start;
  uint32_t flush_n;
  uint32_t flush_px;
  uint32_t bucket[9];
  uint32_t zero_n;
  wp_top_t top[WP_TOP_N];
  uint32_t top_n;
  wp_flush_t fl[WP_FLUSH_N];
  uint32_t fl_n;
} s_probe;

static const char *inval_obj_kind(const lv_obj_t *obj)
{
  if (obj == NULL) {
    return "?";
  }
  if (lv_obj_check_type(obj, &lv_canvas_class)) {
    return "canvas";
  }
  if (lv_obj_check_type(obj, &lv_label_class)) {
    return "label";
  }
  if (lv_obj_check_type(obj, &lv_obj_class)) {
    return "obj";
  }
  return "widget";
}

static const char *inval_obj_text(const lv_obj_t *obj)
{
  if (obj != NULL && lv_obj_check_type(obj, &lv_label_class)) {
    const char *t = lv_label_get_text(obj);
    if (t != NULL) {
      return t;
    }
  }
  return "";
}

static uint32_t inval_bucket(int32_t w, int32_t h)
{
  int32_t m = (w > h) ? w : h;

  if (m <= 8) {
    return 0;
  }
  if (m <= 16) {
    return 1;
  }
  if (m <= 24) {
    return 2;
  }
  if (m <= 32) {
    return 3;
  }
  if (m <= 48) {
    return 4;
  }
  if (m <= 64) {
    return 5;
  }
  if (m <= 128) {
    return 6;
  }
  if (m <= 256) {
    return 7;
  }
  return 8;
}

static void wp_top_reset_slot(wp_top_t *slot, const lv_obj_t *obj,
                              const lv_area_t *area, uintptr_t ra)
{
  memset(slot, 0, sizeof(*slot));
  slot->w = lv_area_get_width(area);
  slot->h = lv_area_get_height(area);
  slot->x = area->x1;
  slot->y = area->y1;
  slot->ra = ra;
  slot->kind = inval_obj_kind(obj);
  slot->obj = obj;
  snprintf(slot->txt, sizeof(slot->txt), "%s", inval_obj_text(obj));
}

static void wp_top_add(const lv_obj_t *obj, const lv_area_t *area, uintptr_t ra)
{
  int32_t w = lv_area_get_width(area);
  int32_t h = lv_area_get_height(area);
  uint32_t i;
  wp_top_t *slot = NULL;

  for (i = 0; i < s_probe.top_n; i++) {
    wp_top_t *t = &s_probe.top[i];

    if (t->w == w && t->h == h && t->x == area->x1 && t->y == area->y1 &&
        t->ra == ra) {
      slot = t;
      break;
    }
  }

  if (slot == NULL) {
    if (s_probe.top_n < WP_TOP_N) {
      slot = &s_probe.top[s_probe.top_n++];
    } else {
      /* 满了就替换当前最少的一条（粗粒度 Top N，够归因用）。 */
      slot = &s_probe.top[0];
      for (i = 1; i < WP_TOP_N; i++) {
        if (s_probe.top[i].n < slot->n) {
          slot = &s_probe.top[i];
        }
      }
    }
    wp_top_reset_slot(slot, obj, area, ra);
  }

  slot->n++;
  slot->px += (uint32_t)w * (uint32_t)h;
}

static void wp_flush_add(const lv_area_t *area)
{
  uint32_t i;
  wp_flush_t *slot = NULL;

  for (i = 0; i < s_probe.fl_n; i++) {
    if (s_probe.fl[i].x1 == area->x1 && s_probe.fl[i].y1 == area->y1 &&
        s_probe.fl[i].x2 == area->x2 && s_probe.fl[i].y2 == area->y2) {
      slot = &s_probe.fl[i];
      break;
    }
  }

  if (slot == NULL) {
    if (s_probe.fl_n < WP_FLUSH_N) {
      slot = &s_probe.fl[s_probe.fl_n++];
    } else {
      slot = &s_probe.fl[0];
      for (i = 1; i < WP_FLUSH_N; i++) {
        if (s_probe.fl[i].n < slot->n) {
          slot = &s_probe.fl[i];
        }
      }
    }
    slot->x1 = area->x1;
    slot->y1 = area->y1;
    slot->x2 = area->x2;
    slot->y2 = area->y2;
    slot->n = 0;
  }

  slot->n++;
}

/**
 * @brief WP-UIFIX 临时对象级钩子（由 lv_obj_pos.c 的 weak 符号调用）。
 */
void bicycle_inval_probe_obj_each(const lv_obj_t *obj, const lv_area_t *area,
                                  unsigned long ra)
{
  int32_t w;
  int32_t h;

  if (area == NULL) {
    return;
  }

  w = lv_area_get_width(area);
  h = lv_area_get_height(area);

  s_probe.obj_n++;
  if (w <= 0 || h <= 0) {
    s_probe.zero_n++;
    return;
  }

  s_probe.obj_px += (uint32_t)w * (uint32_t)h;
  s_probe.bucket[inval_bucket(w, h)]++;
  wp_top_add(obj, area, (uintptr_t)ra);
}

